import sys,glob
d=sys.argv[1]
def rep(p,old,new):
    s=open(p).read(); assert s.count(old)==1,(p,old[:70],s.count(old)); open(p,'w').write(s.replace(old,new))
R=d+"/README.md"
rep(R,"""It takes four hypotheses:
- `w : KatoLocalWitness`, a local-existence witness.
- `hRiccati : FrohmanianTetherBound`, a time-uniform bound on $\\|\\omega\\|_\\infty$. It is used only through its finite-horizon consequence `PhysicalFiniteTimeVorticityBound`. Both are open.
- `hrestart`, uniform restart of the local solution.
- `huniq`, local uniqueness.""","""It takes four hypotheses:
- `w : KatoLocalWitness`, a local-existence witness. It gives $T^\\ast>0$.
- `hRiccati : FrohmanianTetherBound`, a time-uniform bound on $\\|\\omega\\|_\\infty$. It is used through its finite-horizon consequence `PhysicalFiniteTimeVorticityBound`, which gives $\\int_0^T\\|\\omega\\|_\\infty<\\infty$ for every $T$. Both are open.
- `hcrit : PhysicalBKMContinuationCriterionFor`, the Beale–Kato–Majda continuation criterion: if $T^\\ast$ is finite, $\\|\\omega\\|_\\infty$ is not integrable on $[0,T^\\ast]$. Classical, not formalized here.
- `huniq : KatoUniquenessOnExistenceTimes`, local uniqueness. Classical, not formalized here.

$T^\\ast=\\infty$ is derived from $T^\\ast>0$, `hcrit` and the integrability (`NavierStokes3D.Tstar_eq_top_of_bkm`).""")
rep(R,"""  - Theorems taking the finite-horizon form: `global_regularity` and `ClosureBlueprint.continuation_under_global_existence` (`FiniteTimeVorticityBound`), `global_regularity_of_bkmIntegrability` (`BKMIntegrability`), `global_regularity_of_restart` and `global_regularity_of_kato_estimates` (`PhysicalFiniteTimeVorticityBound`).
  - In this formalization the BKM step `NavierStokes3D.beale_kato_majda` closes from `Tstar = ⊤` and smoothness below `Tstar`. The integrability input is carried but not used, and continuity of $t\\mapsto\\|\\omega(t)\\|_\\infty$ on $\\mathbb{R}$ already gives integrability on each $[0,T]$. The open content of these theorems is therefore in the continuation hypotheses (`hTstar`, `hbelow`, `hrestart`, `huniq`) and in continuity of the vorticity norm for all time, not in the size of $C(T)$.""","""  - BKM step. `NavierStokes3D.beale_kato_majda` takes `LocalExistenceTime u ν` ($T^\\ast>0$), `BKMContinuationCriterion u ν`, `PathBKMIntegrable u` and `SmoothBelowTstar u ν`, and proves smoothness for all $t\\ge0$. $T^\\ast=\\infty$ is derived from the first three (`Tstar_eq_top_of_bkm`), and the integrability is needed: `bkm_criterion_without_integrability_not_top` exhibits $T^\\ast=1$, $f(t)=1/t$ satisfying the criterion and $T^\\ast>0$ with $T^\\ast\\ne\\infty$. `BKMContinuationCriterion`, `SmoothBelowTstar` and `LocalExistenceTime` are named `Prop`s; the first two are classical and not formalized here. The u₀-level versions are `BKMContinuationCriterionFor`, `PhysicalBKMContinuationCriterionFor` and `SmoothBelowTstarFor`.
  - Theorems through this BKM step: `global_regularity` (`FiniteTimeVorticityBound`), `global_regularity_of_bkmIntegrability` (`BKMIntegrability`), `global_regularity_of_bkm_uniqueness` and both `global_regularity_for_NS` (`PhysicalFiniteTimeVorticityBound`, with `KatoUniquenessOnExistenceTimes`), `AnalyticPipeline.bkm_regularity_pipeline`, `ClosureBlueprint.beale_kato_majda_criterion`, `regularity_from_riccati_majorant` and `type_composition_sequence`.
  - Scaffolding that does not use integrability: `beale_kato_majda_scaffold` takes `TstarIsTop u ν` and `SmoothBelowTstar u ν`; `beale_kato_majda_scaffold_integrability_unused` proves its conclusion from those two alone. `global_regularity_scaffold` and `ClosureBlueprint.continuation_under_global_existence` take `TstarIsTop` for every path. `global_regularity_of_restart`, `global_regularity_of_kato_estimates` and `global_regularity_of_constructions` derive $T^\\ast=\\infty$ from `KatoUniformRestart u₀ ν τ` alone (`Tstar_top_of_restart_without_vorticity_bound`), so their vorticity hypothesis is not used for global existence.""")
rep(R,"conditional on `w`, `hRiccati`, `hrestart`, `huniq`)","conditional on `w`, `hRiccati`, `hcrit`, `huniq`)")
rep(R,"`type_composition_sequence` conditional on `hRiccati`, `hTstar`, `hbelow`)","`type_composition_sequence` conditional on `hRiccati`, `hcrit`, `hbelow`)")
for P in glob.glob(d+"/paper/*.tex"):
    rep(P,"\\texttt{KatoLocalWitness}, \\texttt{hrestart} and \\texttt{huniq}.","\\texttt{KatoLocalWitness}, \\texttt{PhysicalBKMContinuationCriterionFor} and \\texttt{KatoUniquenessOnExistenceTimes}.")
    rep(P,"uniform restart \\texttt{hrestart}, and local uniqueness \\texttt{huniq}.","the Beale--Kato--Majda continuation criterion \\texttt{PhysicalBKMContinuationCriterionFor}, and local uniqueness \\texttt{KatoUniquenessOnExistenceTimes}. $T^\\ast=\\infty$ is derived from $T^\\ast>0$, the criterion and the integrability.")
    rep(P,"""\\texttt{global\\_regularity}, \\texttt{global\\_regularity\\_of\\_bkmIntegrability}, \\texttt{global\\_regularity\\_of\\_restart}, \\texttt{global\\_regularity\\_of\\_kato\\_estimates} and \\texttt{continuation\\_under\\_global\\_existence} take the finite-horizon form. In this formalization the Beale--Kato--Majda step closes from $T^\\ast=\\infty$ and smoothness below $T^\\ast$; the integrability input is carried but not used. The open content is therefore in the continuation hypotheses and in continuity of $\\|\\omega(t)\\|_\\infty$ for all time.""","""The Beale--Kato--Majda step \\texttt{beale\\_kato\\_majda} takes $T^\\ast>0$ (\\texttt{LocalExistenceTime}), the continuation criterion (\\texttt{BKMContinuationCriterion}: finite $T^\\ast$ forces $\\int_0^{T^\\ast}\\|\\omega\\|_\\infty=\\infty$), integrability on every $[0,T]$ (\\texttt{PathBKMIntegrable}) and smoothness below $T^\\ast$ (\\texttt{SmoothBelowTstar}); $T^\\ast=\\infty$ is derived (\\texttt{Tstar\\_eq\\_top\\_of\\_bkm}), and the integrability is necessary (\\texttt{bkm\\_criterion\\_without\\_integrability\\_not\\_top}). \\texttt{global\\_regularity}, \\texttt{global\\_regularity\\_of\\_bkmIntegrability}, \\texttt{global\\_regularity\\_of\\_bkm\\_uniqueness} and \\texttt{global\\_regularity\\_for\\_NS} go through this step. The criterion and smoothness below $T^\\ast$ are classical and not formalized here. \\texttt{beale\\_kato\\_majda\\_scaffold} assumes $T^\\ast=\\infty$ and does not use integrability (\\texttt{beale\\_kato\\_majda\\_scaffold\\_integrability\\_unused}); \\texttt{global\\_regularity\\_of\\_restart}, \\texttt{global\\_regularity\\_of\\_kato\\_estimates} and \\texttt{continuation\\_under\\_global\\_existence} derive or assume $T^\\ast=\\infty$ without the vorticity input.""")
    rep(P,"non-vacuously inhabited at $u_0 \\equiv 0$, and tethered flows satisfy $T^*(u_0, \\nu) = \\top$.","non-vacuously inhabited at $u_0 \\equiv 0$; \\texttt{global\\_regularity\\_for\\_NS} is conditional on its stated hypotheses.")
